# -*- coding: utf-8 -*-
"""Generate Angela Mobile Legends alert fragments and CSS."""
from pathlib import Path
BASE = Path(__file__).parent
RAW_BG = 'https://raw.githubusercontent.com/MasAjie12/angela-mobile-legends-alert-assets/main/bg.png'
RAW_TOP = 'https://raw.githubusercontent.com/MasAjie12/angela-mobile-legends-alert-assets/main/hiasankananatasbaru.png'
RAW_BOTTOM = 'https://raw.githubusercontent.com/MasAjie12/angela-mobile-legends-alert-assets/main/hiasankananbawahnobg.png'
CSS = f'''html,body{{overflow:hidden!important}}.an30-card{{box-sizing:border-box;position:relative;isolation:isolate;display:flex;align-items:center;justify-content:center;width:720px;max-width:100%;height:280px;margin:0 auto;overflow:hidden;border:3px solid #F39BC8;border-radius:24px;background:#5B4D9A;color:#FFF;font-family:'Trebuchet MS','Segoe UI',sans-serif;text-align:center;box-shadow:0 12px 34px rgba(42,24,83,.65),0 0 26px rgba(255,157,211,.42),inset 0 0 0 2px rgba(255,255,255,.7);animation:an30-in .7s cubic-bezier(.2,.9,.25,1.12) both,an30-breathe 5s ease-in-out .7s infinite}}.an30-bg{{position:absolute;top:0;left:0;width:100%;height:100%;z-index:0;object-fit:cover;filter:saturate(1.12) brightness(.92);animation:an30-zoom 16s ease-in-out infinite alternate}}.an30-veil{{position:absolute;top:0;left:0;right:0;bottom:0;z-index:1;background:linear-gradient(90deg,rgba(47,31,105,.08),rgba(41,25,91,.22)),linear-gradient(180deg,rgba(255,168,216,.03),rgba(37,24,86,.18))}}.an30-top,.an30-bottom{{position:absolute;z-index:4;pointer-events:none;object-fit:contain;filter:drop-shadow(0 7px 12px rgba(35,17,75,.62))}}.an30-top{{top:-14px;right:-14px;width:clamp(82px,18%,150px);animation:an30-float 4s ease-in-out infinite}}.an30-bottom{{right:-26px;bottom:-18px;width:clamp(130px,36%,270px);opacity:.72;animation:an30-ribbon 5s ease-in-out infinite}}.an30-c{{position:relative;z-index:6;box-sizing:border-box;width:66%;min-width:0;padding:0 14px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-shadow:0 2px 8px rgba(35,17,75,.95)}}.an30-c::before{{content:"";position:absolute;top:-18px;right:-18px;bottom:-18px;left:-18px;z-index:-1;pointer-events:none;background:radial-gradient(ellipse,rgba(24,10,60,.58),rgba(24,10,60,.22) 62%,transparent 100%);filter:blur(10px)}}.an30-c>*{{position:relative;z-index:1}}.an30-kicker{{color:#FFE6F5;font-size:11px;font-weight:900;letter-spacing:2.2px;text-transform:uppercase;text-shadow:0 2px 6px #321A68,0 0 14px rgba(255,182,224,.8);animation:an30-rise .6s cubic-bezier(.2,.9,.3,1.2) .1s both}}.an30-amount{{margin:4px 0;font-size:38px;font-weight:900;line-height:1.1;letter-spacing:1px;color:#FFF8FD;word-break:break-all;max-width:100%;text-shadow:0 3px 0 #70408D,0 0 22px rgba(255,171,224,.9);animation:an30-rise .6s cubic-bezier(.2,.9,.3,1.2) .18s both,an30-glow 3.4s ease-in-out 1s infinite}}.an30-tag{{margin-top:4px;color:#FFD0EA;font-size:12px;font-weight:900;letter-spacing:1.4px;text-transform:uppercase;animation:an30-rise .6s cubic-bezier(.2,.9,.3,1.2) .26s both}}.an30-who{{margin-top:4px;min-width:0;max-width:100%;animation:an30-rise .6s cubic-bezier(.2,.9,.3,1.2) .34s both}}.an30-name{{display:block;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:27px;font-weight:900;color:#FFF;text-shadow:0 2px 0 #321A68,0 2px 10px #211145,0 0 14px rgba(255,232,247,.6)}}.an30-msg{{margin-top:6px;font-size:18px;font-weight:600;line-height:1.35;color:#FFF1FA;max-width:100%;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;animation:an30-rise .6s cubic-bezier(.2,.9,.3,1.2) .42s both}}@keyframes an30-in{{0%{{opacity:0;transform:translateY(22px) scale(.94)}}100%{{opacity:1;transform:none}}}}@keyframes an30-breathe{{0%,100%{{box-shadow:0 12px 34px rgba(42,24,83,.65),0 0 20px rgba(255,157,211,.28),inset 0 0 0 2px rgba(255,255,255,.55)}}50%{{box-shadow:0 12px 38px rgba(42,24,83,.7),0 0 38px rgba(255,157,211,.6),inset 0 0 0 2px rgba(255,255,255,.82)}}}}@keyframes an30-zoom{{from{{transform:scale(1)}}to{{transform:scale(1.08) translateY(-1%)}}}}@keyframes an30-rise{{from{{opacity:0;transform:translateY(10px)}}to{{opacity:1;transform:translateY(0)}}}}@keyframes an30-glow{{0%,100%{{text-shadow:0 3px 0 #70408D,0 0 18px rgba(255,171,224,.65)}}50%{{text-shadow:0 3px 0 #70408D,0 0 32px rgba(255,224,244,1)}}}}@keyframes an30-float{{0%,100%{{transform:translateY(0) rotate(0deg)}}50%{{transform:translateY(-7px) rotate(2deg)}}}}@keyframes an30-ribbon{{0%,100%{{transform:translateY(0)}}50%{{transform:translateY(-5px)}}}}@media(max-width:560px){{.an30-card{{height:220px;border-radius:18px}}.an30-c{{width:68%;padding:0 8px}}.an30-amount{{font-size:clamp(27px,8vw,36px)}}.an30-name{{font-size:clamp(19px,6vw,27px)}}.an30-msg{{font-size:14px}}.an30-top{{width:31%}}.an30-bottom{{width:65%}}}}@media(prefers-reduced-motion:reduce){{.an30-card,.an30-bg,.an30-top,.an30-bottom,.an30-kicker,.an30-amount,.an30-tag,.an30-who,.an30-msg{{animation:none!important}}}}'''

def build(name, tag=''):
    return f'<div class="an30-card"><img class="an30-bg" src="{RAW_BG}" alt=""><div class="an30-veil"></div><img class="an30-top" src="{RAW_TOP}" alt=""><img class="an30-bottom" src="{RAW_BOTTOM}" alt=""><div class="an30-c"><div class="an30-kicker">DUKUNGAN MASUK</div><div class="an30-amount">{{amount}}</div>{tag}<div class="an30-who"><span class="an30-name">{name}</span></div><div class="an30-msg">{{message}}</div></div></div>'

for slug, name, tag in [('sociabuzz','{supporter}','<div class="an30-tag">{from_text}</div>'),('saweria','{donator}','')]:
    (BASE / f'{slug}-alert.html').write_text(build(name, tag), encoding='utf-8')
    (BASE / f'{slug}-alert.css').write_text(CSS, encoding='utf-8')
assert len(CSS.encode()) <= 5120
assert CSS.count('{') == CSS.count('}')
for slug in ('sociabuzz','saweria'):
    html = (BASE / f'{slug}-alert.html').read_text(encoding='utf-8')
    assert '\n' not in html and '<style' not in html and 'style="' not in html
assert '{supporter}' in (BASE/'sociabuzz-alert.html').read_text()
assert '{from_text}' in (BASE/'sociabuzz-alert.html').read_text()
assert '{donator}' in (BASE/'saweria-alert.html').read_text()
print('OK alert CSS', len(CSS.encode()), 'bytes')